cat > package.json <<'EOF'
{
  "name": "qrypt-aes256-key",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "description": "Generate an AES-256 key from Qrypt quantum entropy",
  "engines": { "node": ">=20.12" },
  "scripts": { "start": "node generate-key.js" }
}
EOF
cat > .gitignore <<'EOF'
.env
node_modules/
EOF
cat > generate-key.js <<'EOF'
// Generate an AES-256 key from Qrypt quantum entropy and verify it with an
// AES-256-GCM round trip. The key and API token are never printed or saved.
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";
import { fileURLToPath } from "node:url";
import path from "node:path";

const ENTROPY_URL = "https://api-eus.qrypt.com/api/v1/quantum-entropy";

process.loadEnvFile(path.join(path.dirname(fileURLToPath(import.meta.url)), ".env"));
const token = process.env.QRYPT_API_KEY;
if (!token) {
  console.error("QRYPT_API_KEY is not set in .env");
  process.exit(1);
}

async function fetchQuantumKey() {
  // size is in KiB (1-512); 1 KiB is plenty for a 32-byte key.
  const res = await fetch(`${ENTROPY_URL}?size=1`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  if (!res.ok) {
    const hints = {
      400: "size out of range",
      401: "missing, malformed, or expired token",
      403: "invalid token or monthly quota exhausted",
      429: "rate limited; wait at least 10 seconds before retrying",
    };
    const hint = hints[res.status] ?? (res.status >= 500 ? "service busy; try again later" : "");
    throw new Error(`Qrypt API returned ${res.status}${hint ? ` (${hint})` : ""}`);
  }
  const { random } = await res.json();
  const entropy = Buffer.from(random[0], "base64");
  if (entropy.length < 32) throw new Error("Not enough entropy returned");
  return entropy.subarray(0, 32);
}

function roundTrip(key) {
  const iv = randomBytes(12);
  const plaintext = Buffer.from("Hello, quantum-safe world!");
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();

  const decipher = createDecipheriv("aes-256-gcm", key, iv);
  decipher.setAuthTag(tag);
  const decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  return decrypted.equals(plaintext);
}

try {
  const key = await fetchQuantumKey();
  console.log(`Generated AES-256 key from quantum entropy (${key.length * 8} bits)`);
  console.log(`AES-256-GCM round trip: ${roundTrip(key) ? "OK" : "FAILED"}`);
  key.fill(0);
} catch (err) {
  console.error(err.message);
  process.exit(1);
}
EOF
node --check generate-key.js && echo syntax ok; node generate-key.js; echo "exit=$?"

